using System.Reflection;
using Microsoft.JSInterop;
using Playbook.Samples;
var type = typeof(Worksheet);
foreach (var disconnect in new[] { false, true })
{
    var instance = new Worksheet();
    type.GetProperty("JS", BindingFlags.Instance | BindingFlags.NonPublic)!.SetValue(instance, new FailingJs(disconnect));
    var task = (Task)type.GetMethod("HoldAsync", BindingFlags.Instance | BindingFlags.NonPublic)!.Invoke(instance, null)!;
    try { await task; if (!disconnect) throw new Exception("Failure was swallowed."); }
    catch (JSException) when (!disconnect) { }
    if ((bool)type.GetField("busy", BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(instance)!) throw new Exception("busy remained true");
    Console.WriteLine($"PASS actual Worksheet HoldAsync: {(disconnect ? "disconnect contained" : "JSException propagated")}; busy=False");
}
sealed class FailingJs(bool disconnect) : IJSRuntime
{
    public ValueTask<T> InvokeAsync<T>(string identifier, object?[]? args) => InvokeAsync<T>(identifier, default, args);
    public ValueTask<T> InvokeAsync<T>(string identifier, CancellationToken cancellationToken, object?[]? args) => ValueTask.FromException<T>(disconnect ? new JSDisconnectedException("fixture disconnect") : new JSException("fixture rejected promise"));
}

